w = csv.writer(open(sys.argv[1], 'w', newline=''))
w.writerow(['column','group','type','units','definition'])
w.writerows(D)
import pandas as pd
cols = pd.read_csv(sys.argv[2], nrows=1).columns.tolist()
assert cols == [d[0] for d in D], set(cols) ^ {d[0] for d in D}
print(len(D), 'ok')
